  const [contentCategory, setContentCategory] = useState(detailText(current?.details, "contentCategory"));
  const [audienceScale, setAudienceScale] = useState(detailText(current?.details, "audienceScale"));
  const [channel, setChannel] = useState(detailText(current?.details, "channel"));
  const [budget, setBudget] = useState(detailText(current?.details, "budget"));
  const [commission, setCommission] = useState(detailText(current?.details, "commission"));
  const [benefits, setBenefits] = useState(detailText(current?.details, "benefits"));
  const [deliverables, setDeliverables] = useState(detailText(current?.details, "deliverables"));
  const [evidence, setEvidence] = useState(detailText(current?.details, "evidence"));
  const [schedule, setSchedule] = useState(detailText(current?.details, "schedule"));
  useEffect(() => { const details = current?.details; setTitle(current?.title ?? copy.defaultTitle); setSummary(current?.summary ?? ""); setOwner(detailText(details, "owner") || "经营负责人"); setProductRef(detailText(details, "productRef") || products[0]?.productRef.resourceId || ""); setCandidateSource(detailText(details, "candidateSource")); setContentCategory(detailText(details, "contentCategory")); setAudienceScale(detailText(details, "audienceScale")); setChannel(detailText(details, "channel")); setBudget(detailText(details, "budget")); setCommission(detailText(details, "commission")); setBenefits(detailText(details, "benefits")); setDeliverables(detailText(details, "deliverables")); setEvidence(detailText(details, "evidence")); setSchedule(detailText(details, "schedule")); }, [current?.revision, purpose, products]);
  const selectedProduct = products.find((item) => item.productRef.resourceId === productRef);
  const values = { title: title.trim(), summary: summary.trim(), details: { owner: owner.trim(), productRef, productName: selectedProduct?.title ?? detailText(current?.details, "productName"), candidateSource: candidateSource.trim(), contentCategory: contentCategory.trim(), audienceScale: audienceScale.trim(), channel: channel.trim(), budget: budget.trim(), commission: commission.trim(), benefits: benefits.trim(), deliverables: deliverables.trim(), evidence: evidence.trim(), schedule: schedule.trim() } };
  const disabled = busy || readUnavailable || values.title.length < 2 || values.summary.length < 2;
  return <aside className="creator-growth-preparation" aria-label={copy.title}><header><div><span>内部业务工作流</span><h2>{copy.title}</h2></div><button type="button" onClick={onClose}>关闭</button></header>
    <label>任务名称<input aria-label="任务名称" value={title} onChange={(event) => setTitle(event.target.value)} /></label>
    <label>{copy.summaryLabel}<textarea aria-label={copy.summaryLabel} value={summary} onChange={(event) => setSummary(event.target.value)} placeholder={copy.placeholder} /></label>
    <label>关联商品<select aria-label="关联商品" value={productRef} onChange={(event) => setProductRef(event.target.value)}><option value="">暂不关联商品</option>{products.map((item) => <option key={item.productRef.resourceId} value={item.productRef.resourceId}>{item.title}{item.availableStock === null ? "" : ` · 库存 ${item.availableStock}`}</option>)}</select></label>
