    {purpose === "outreach_batch" || purpose === "outreach_message" ? <div className="creator-growth-business-fields"><label>邀约渠道<input aria-label="邀约渠道" value={channel} onChange={(event) => setChannel(event.target.value)} placeholder="例如：站内私信" /></label><label>合作权益<input aria-label="合作权益" value={benefits} onChange={(event) => setBenefits(event.target.value)} placeholder="例如：寄样与专属佣金" /></label><label>回复期限<input aria-label="回复期限" value={schedule} onChange={(event) => setSchedule(event.target.value)} placeholder="例如：3个工作日内" /></label></div> : null}
    {purpose === "collaboration" ? <div className="creator-growth-business-fields"><label>合作预算<input aria-label="合作预算" value={budget} onChange={(event) => setBudget(event.target.value)} placeholder="例如：3000元" /></label><label>佣金条件<input aria-label="佣金条件" value={commission} onChange={(event) => setCommission(event.target.value)} placeholder="例如：成交额的15%" /></label><label>合作权益<input aria-label="合作权益" value={benefits} onChange={(event) => setBenefits(event.target.value)} placeholder="例如：寄样与专属优惠券" /></label><label>约定交付物<input aria-label="约定交付物" value={deliverables} onChange={(event) => setDeliverables(event.target.value)} placeholder="例如：图文1篇、短视频1条" /></label><label>合作档期<input aria-label="合作档期" value={schedule} onChange={(event) => setSchedule(event.target.value)} placeholder="例如：9月15日前发布" /></label></div> : null}
    {purpose === "delivery_check" ? <div className="creator-growth-business-fields"><label>约定交付物<input aria-label="约定交付物" value={deliverables} onChange={(event) => setDeliverables(event.target.value)} placeholder="例如：图文1篇、短视频1条" /></label><label>验收证据<input aria-label="验收证据" value={evidence} onChange={(event) => setEvidence(event.target.value)} placeholder="例如：内容链接、平台截图、数据报表" /></label><label>验收时间<input aria-label="验收时间" value={schedule} onChange={(event) => setSchedule(event.target.value)} placeholder="例如：发布后7天" /></label></div> : null}
