    {readUnavailable ? <p role="alert">当前内部草稿暂未读取，暂存内容不能作为当前版本操作。请重新读取后再准备或评审。</p> : null}
    {current ? <section aria-label={readUnavailable ? "上次读取草稿" : "当前草稿"}><strong>{readUnavailable ? "上次读取：" : ""}{WORKFLOW_STATUS[current.status]} · 第 {current.revision} 版</strong><small>{readUnavailable ? "暂存版本" : "写入基线"} {current.version} · {current.resourceId}</small>{receipt ? <small>回执 {receipt.receiptId}{receipt.replay ? " · 幂等重放" : ""}</small> : null}</section> : null}
    {error ? <p role="alert">{error}</p> : null}
    <div className="creator-growth-preparation-actions">
      {!current ? <button type="button" className="is-primary" disabled={disabled} onClick={() => onCommand("create", values)}>保存草稿</button> : null}
      {current && (current.status === "draft" || current.status === "rejected") ? <><button type="button" disabled={disabled} onClick={() => onCommand("save", values)}>保存修改</button><button type="button" className="is-primary" disabled={disabled} onClick={() => onCommand("submit_review", values)}>提交审核</button></> : null}
      {current?.status === "in_review" ? <><button type="button" className="is-primary" disabled={busy || readUnavailable} onClick={() => onCommand("approve", values)}>批准</button><button type="button" disabled={busy || readUnavailable} onClick={() => onCommand("reject", values)}>驳回</button></> : null}
      {current ? <button type="button" disabled={busy || readUnavailable} onClick={onNew}>新建一份</button> : null}
    </div>
